const input = $('Workflow Input').item.json;
if (!input.TEMA_ARTICULO || input.TEMA_ARTICULO === 'undefined' || !input.TEMA_ARTICULO.trim()) {
  throw new Error('VALIDATION_FAILED: TEMA_ARTICULO vacío');
}
if (!input.ID_BLOG || input.ID_BLOG === 'undefined') {
  throw new Error('VALIDATION_FAILED: ID_BLOG vacío');
}

const allConfigs = $('Read NICHE_CONFIG').all().map(i => i.json);
let cfg = allConfigs.find(c => c.ID_BLOG === input.ID_BLOG) ||
          allConfigs.find(c => c.NICHO === input.NICHO) || null;
if (!cfg) {
  cfg = { ID_BLOG: input.ID_BLOG, NICHO: input.NICHO || 'general',
    IDIOMA: input.IDIOMA || 'es', SITIO_URL: '', BLOGGER_ID: '',
    TONE: 'informativo, experto', AUDIENCE: 'lectores interesados', MIN_WORDS: 1300, MAX_WORDS: 1800, PROMPT_EXTRA: '' };
}

const lang   = cfg.IDIOMA || input.IDIOMA || 'es';
const niche  = cfg.NICHO  || input.NICHO  || 'general';
const es     = lang === 'es';
const minWords = Number(cfg.MIN_WORDS) || 1300;
const maxWords = Number(cfg.MAX_WORDS) || 1800;
const tone   = cfg.TONE || 'informativo, experto, práctico';
const audience = cfg.AUDIENCE || 'lectores del tema';
const promptExtra = cfg.PROMPT_EXTRA || '';

// ── Clasificación de nicho ────────────────────────────────────────────────────
const HIGH_RPM_NICHES = ['abogad', 'impuest', 'legal', 'segur', 'accidente', 'multa',
  'bienes raíc', 'hipotec', 'inmobil', 'salud', 'médic', 'hipertens', 'esclerosis',
  'tax', 'lawyer', 'insurance', 'accident', 'real estate', 'mortgage', 'health'];

const ANIMAL_NICHES = ['veterin', 'mascot', 'perr', 'gat', 'animal', 'pet', 'felino',
  'canino', 'aves', 'reptil', 'acuario', 'exótic', 'farm', 'granja', 'ganado'];

const nichoLower = niche.toLowerCase();
const temaLower = input.TEMA_ARTICULO.toLowerCase();
const isHighRPM = HIGH_RPM_NICHES.some(k => nichoLower.includes(k) || temaLower.includes(k));
const isAnimal  = ANIMAL_NICHES.some(k => nichoLower.includes(k) || temaLower.includes(k));

// ── Autores por nicho (E-E-A-T) ───────────────────────────────────────────────
const authorMap = {
  abogad: 'Lic. Carmen Torres, Abogada con 18 años de experiencia',
  legal:  'Lic. Carmen Torres, Abogada con 18 años de experiencia',
  impuest: 'CPA Roberto Méndez, Contador Público Certificado',
  tax:    'CPA Roberto Méndez, Certified Public Accountant',
  segur:  'Ing. Sofía Ramírez, Asesora de seguros certificada',
  accidente: 'Lic. Jorge Herrera, Abogado especialista en accidentes',
  bienes: 'Arq. Patricia Soto, Agente inmobiliaria certificada',
  salud:  'Dr. Alejandro Cruz, Médico Internista',
  médic:  'Dr. Alejandro Cruz, Médico Internista',
  hipertens: 'Dr. Alejandro Cruz, Médico Internista',
  veterin: 'Dr. Luis Arturo García, Médico Veterinario y Zootecnista',
  mascot:  'Dr. Luis Arturo García, Médico Veterinario y Zootecnista',
  perr:   'Dr. Luis Arturo García, Médico Veterinario y Zootecnista',
  gat:    'Dr. Luis Arturo García, Médico Veterinario y Zootecnista',
};
const author = Object.entries(authorMap).find(([k]) => nichoLower.includes(k) || temaLower.includes(k))?.[1]
  || (isAnimal ? 'Dr. Luis Arturo García, Médico Veterinario y Zootecnista' : 'Equipo Editorial Especializado');

// ── Bloque de autor HTML ──────────────────────────────────────────────────────
const authorBlock = es
  ? `<div class="author-bio" style="background:#f8f9fa;border-left:4px solid #2196F3;padding:16px;margin:24px 0;border-radius:4px">
<strong>Sobre el autor:</strong> ${author}. Este artículo ha sido revisado y verificado con fuentes especializadas.
</div>`
  : `<div class="author-bio" style="background:#f8f9fa;border-left:4px solid #2196F3;padding:16px;margin:24px 0;border-radius:4px">
<strong>About the author:</strong> ${author}. This article has been reviewed and verified with specialized sources.
</div>`;

// ── Disclaimer legal/médico ───────────────────────────────────────────────────
const disclaimerBlock = es
  ? `<div class="disclaimer" style="background:#fff3cd;border:1px solid #ffc107;padding:12px;margin:20px 0;border-radius:4px;font-size:0.9em">
<strong>⚠ Aviso:</strong> Este artículo es de carácter informativo. Consulta siempre a un profesional especializado antes de tomar decisiones basadas en este contenido.
</div>`
  : `<div class="disclaimer" style="background:#fff3cd;border:1px solid #ffc107;padding:12px;margin:20px 0;border-radius:4px;font-size:0.9em">
<strong>⚠ Disclaimer:</strong> This article is for informational purposes only. Always consult a qualified professional before making decisions based on this content.
</div>`;

// ── Schema JSON-LD ───────────────────────────────────────────────────────────
const schemaBlock = `<script type="application/ld+json">
{"@context":"https://schema.org","@type":"Article","headline":"${input.TEMA_ARTICULO.replace(/"/g,"'")}","author":{"@type":"Person","name":"${author.split(',')[0]}"},"publisher":{"@type":"Organization","name":"${niche}"},"datePublished":"${new Date().toISOString().slice(0,10)}","inLanguage":"${lang}","about":{"@type":"Thing","name":"${niche}"}}
</script>`;

// ── Bloque monetización según tipo de nicho ────────────────────────────────────
let monetBlock;
if (isAnimal) {
  monetBlock = es
    ? `BLOQUES DE MONETIZACIÓN PARA BLOG DE MASCOTAS/VETERINARIA (insertar en estas posiciones exactas):

1) Después del 2do párrafo — Productos Amazon para mascotas:
<div class="rec-productos" style="background:#f0f7ff;padding:16px;border-radius:8px;margin:20px 0">
<h3>🐾 Productos recomendados</h3><ul>
<li><!-- PROD1_NAME --> — <a href="<!-- PROD1_URL -->" rel="nofollow sponsored" target="_blank">Ver en Amazon →</a></li>
<li><!-- PROD2_NAME --> — <a href="<!-- PROD2_URL -->" rel="nofollow sponsored" target="_blank">Ver en Amazon →</a></li>
<li><!-- PROD3_NAME --> — <a href="<!-- PROD3_URL -->" rel="nofollow sponsored" target="_blank">Ver en Amazon →</a></li>
</ul></div>

2) A la mitad del artículo — CTA Comunidad:
<div class="cta-telegram" style="background:#e3f2fd;padding:16px;border-radius:8px;margin:20px 0;text-align:center">
<p>💬 ¿Tienes dudas sobre tu mascota? <a href="<!-- TELEGRAM_URL -->" target="_blank"><strong>Únete a nuestra comunidad veterinaria gratuita →</strong></a></p>
</div>

3) Al final del artículo — Infoproducto/consultoría:
<div class="cta-final" style="background:#e8f5e9;padding:20px;border-radius:8px;margin:20px 0;text-align:center">
<h3>📋 Guía completa disponible</h3>
<p><a href="<!-- LEAD_MAGNET_URL -->" target="_blank" style="background:#4CAF50;color:#fff;padding:10px 20px;border-radius:4px;text-decoration:none"><strong><!-- LEAD_MAGNET_NAME --> — Descargar gratis →</strong></a></p>
</div>`
    : `MONETIZATION BLOCKS FOR PET/VETERINARY BLOG:

1) After 2nd paragraph:
<div class="rec-products" style="background:#f0f7ff;padding:16px;border-radius:8px;margin:20px 0">
<h3>🐾 Recommended products</h3><ul>
<li><!-- PROD1_NAME --> — <a href="<!-- PROD1_URL -->" rel="nofollow sponsored" target="_blank">Check on Amazon →</a></li>
<li><!-- PROD2_NAME --> — <a href="<!-- PROD2_URL -->" rel="nofollow sponsored" target="_blank">Check on Amazon →</a></li>
<li><!-- PROD3_NAME --> — <a href="<!-- PROD3_URL -->" rel="nofollow sponsored" target="_blank">Check on Amazon →</a></li>
</ul></div>

2) Mid-article:
<div class="cta-community" style="background:#e3f2fd;padding:16px;border-radius:8px;margin:20px 0;text-align:center">
<p>💬 Questions about your pet? <a href="<!-- TELEGRAM_URL -->" target="_blank"><strong>Join our free veterinary community →</strong></a></p>
</div>

3) End of article:
<div class="cta-final" style="background:#e8f5e9;padding:20px;border-radius:8px;margin:20px 0;text-align:center">
<p><a href="<!-- LEAD_MAGNET_URL -->" target="_blank"><strong><!-- LEAD_MAGNET_NAME --> — Download free →</strong></a></p>
</div>`;
} else {
  // Para blogs Adsense: mínimo de CTAs propios, dejar espacio para anuncios
  monetBlock = es
    ? `BLOQUES DE MONETIZACIÓN INFORMATIVOS (insertar solo estos):

1) A la mitad del artículo, después de un H2 — CTA de valor:
<div class="cta-telegram" style="background:#f8f9fa;padding:16px;border-radius:8px;margin:20px 0">
<p>💬 ¿Dudas? Consúltanos gratis: <a href="<!-- TELEGRAM_URL -->" target="_blank"><!-- TELEGRAM_NAME --></a></p>
</div>

2) Al final:
<div class="cta-final" style="background:#f8f9fa;padding:16px;border-radius:8px;margin:20px 0">
<p>📥 Recurso gratuito: <a href="<!-- LEAD_MAGNET_URL -->" target="_blank"><!-- LEAD_MAGNET_NAME --></a></p>
</div>

IMPORTANTE: NO incluyas listas de productos de Amazon en este artículo. Deja el contenido limpio y de alta calidad para Adsense.`
    : `MONETIZATION BLOCKS:

1) Mid-article CTA:
<div class="cta-help" style="background:#f8f9fa;padding:16px;border-radius:8px;margin:20px 0">
<p>💬 Questions? Get free help: <a href="<!-- TELEGRAM_URL -->" target="_blank"><!-- TELEGRAM_NAME --></a></p>
</div>

2) End of article:
<div class="cta-final" style="background:#f8f9fa;padding:16px;border-radius:8px;margin:20px 0">
<p>📥 Free resource: <a href="<!-- LEAD_MAGNET_URL -->" target="_blank"><!-- LEAD_MAGNET_NAME --></a></p>
</div>

IMPORTANT: Do NOT include Amazon product lists. Keep content clean and high-quality for Adsense.`;
}

// ── Sistema de prompts ────────────────────────────────────────────────────────
const adsenseNote = isHighRPM && es
  ? `Escribe como ${author}. El artículo debe demostrar experiencia real (E-E-A-T). Incluye ejemplos prácticos, casos reales y cita referencias cuando sea relevante. Evita frases genéricas. El contenido debe ser único, útil y de alta calidad. `
  : isHighRPM
  ? `Write as ${author}. Article must demonstrate real expertise (E-E-A-T). Include practical examples, real cases, cite references when relevant. Avoid generic phrases. `
  : '';

const sys = es
  ? `Eres ${author}. Experto en ${niche}. Tono: ${tone}. Audiencia: ${audience}. ${adsenseNote}Escribe SOLO HTML puro sin markdown, sin bloques de código, sin explicaciones previas.`
  : `You are ${author}. Expert in ${niche}. Tone: ${tone}. Audience: ${audience}. ${adsenseNote}Output ONLY pure HTML, no markdown, no code blocks, no preamble.`;

const structureReq = es
  ? `Estructura OBLIGATORIA:
- Empieza con el bloque schema JSON-LD: ${schemaBlock}
- <h1> título optimizado SEO
- Párrafo introductorio con hook (problema/beneficio) — 2 párrafos
${isHighRPM ? `- ${disclaimerBlock}` : ''}
- 5-6 <h2> con 2-3 párrafos sustanciales cada uno (ejemplos, datos, pasos concretos)
- ${authorBlock}
- Conclusión con resumen y CTA claro
- Al final: <p><em>Referencias: [menciona 2-3 fuentes generales relevantes del tema]</em></p>`
  : `MANDATORY structure:
- Start with schema JSON-LD block: ${schemaBlock}
- <h1> SEO-optimized title
- Intro with hook (2 paragraphs)
${isHighRPM ? `- ${disclaimerBlock}` : ''}
- 5-6 <h2> sections with 2-3 substantial paragraphs each
- ${authorBlock}
- Conclusion with CTA
- <p><em>References: [mention 2-3 relevant general sources]</em></p>`;

const usr = es
  ? `Escribe en español un artículo sobre: "${input.TEMA_ARTICULO}"
Keywords principales: ${input.KEYWORD || ''}
Extensión: ${minWords}-${maxWords} palabras de contenido real (sin contar HTML)
${promptExtra}

${structureReq}

${monetBlock}

Empieza DIRECTAMENTE con el script JSON-LD, luego <h1>.`
  : `Write in English an article about: "${input.TEMA_ARTICULO}"
Main keywords: ${input.KEYWORD || ''}
Length: ${minWords}-${maxWords} words of real content (not counting HTML)
${promptExtra}

${structureReq}

${monetBlock}

Start DIRECTLY with the JSON-LD script, then <h1>.`;

return { json: {
  ...input,
  bloggerId:    cfg.BLOGGER_ID || '',
  nicheDisplay: niche,
  systemPrompt: sys,
  userPrompt:   usr,
  language:     lang,
  isHighRPM,
  isAnimal,
  author
}};

const res = $('DeepSeek API').item.json;
const prev = $('Build Prompt + Monetizacion').item.json;
if (!res.choices || !res.choices[0]) {
  throw new Error('DeepSeek sin choices: ' + JSON.stringify(res).substring(0, 300));
}
let html = (res.choices[0].message.content || '').trim();
if (!html || html.length < 200) throw new Error('HTML vacío o muy corto');
// Limpiar markdown fences si DeepSeek los añadió
html = html.replace(/^```html\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```\s*$/i, '').trim();
if (!html.includes('<h') || !html.includes('<p>')) throw new Error('HTML sin estructura válida: faltan h o p');
const words = html.replace(/<[^>]+>/g, ' ').split(/\s+/).filter(w => w.length > 2).length;
const tok = res.usage || {};
return { json: {
  ID_UNICO: prev.ID_UNICO,
  TEMA_ARTICULO: prev.TEMA_ARTICULO,
  ID_BLOG: prev.ID_BLOG,
  BLOGGER_ID: prev.bloggerId,
  NICHO: prev.nicheDisplay,
  IDIOMA: prev.language,
  HTML_FINAL: html,
  WORD_COUNT: words,
  TOKENS_USED: tok.total_tokens || 0,
  GENERATED_AT: new Date().toISOString(),
  HAS_MONETIZATION: html.includes('PROD1_NAME') || html.includes('cta-telegram')
}};

const prev = $('Build Prompt + Monetizacion').item.json;
const retries = parseInt(prev.RETRY_COUNT||'0');
if (retries >= 2) throw new Error('DeepSeek fallo 3 veces consecutivas');
return { json: { ...prev, RETRY_COUNT: retries + 1 } };

const d = $('Extraer y Validar HTML').item.json;
return { json: {
  HTML_FINAL: d.HTML_FINAL,
  ID_UNICO: d.ID_UNICO,
  TEMA_ARTICULO: d.TEMA_ARTICULO,
  ID_BLOG: d.ID_BLOG,
  BLOGGER_ID: d.BLOGGER_ID,
  NICHO: d.NICHO,
  IDIOMA: d.IDIOMA,
  TOKENS_USED: d.TOKENS_USED,
  WORD_COUNT: d.WORD_COUNT,
  HAS_MONETIZATION: d.HAS_MONETIZATION
}};
